// @ts-nocheck -- type-checked in the motion-film project, not here.
// Generated by scripts/sync-film.mjs from motion-film/src/scenes/BaraatScene.tsx. Edit it there, then run `npm run sync:film`.
import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { Camera, ParallaxLayer, useCamera } from "../camera/Camera";
import { Stage } from "../stage/Stage";
import { SceneLighting } from "../stage/SceneLighting";
import { PaperBackground } from "../paper/PaperBackground";
import { GoldFrame } from "../ornaments/GoldFrame";
import { Cloud, PalaceSkyline, SkyGradient, SunOnWire } from "../sets/Sky";
import { HaveliRow, WelcomeGate } from "../sets/WeddingDayStreet";
import { Bunting, Dhol, Ghodi, Umbrella } from "../props/WeddingDayBaraat";
import { Figure, Gate, SVG, fig, handAt, reach, reachPose, toScene, type Fig, type Pt } from "../props/WeddingDayKit";
import { people, wardrobe } from "../characters/cast";
import type { Pose } from "../characters/types";
import { Flower, GarlandSwag, Leaf, Petal } from "../props/Florals";
import { FallingPetals } from "../kit/Particles";
import { EventTitle } from "../kit/EventTitle";
import { EASE, prog, wave } from "../kit/motion";
import { palette } from "../theme/palette";
import type { SceneProps } from "./types";
import { bi, whenBi } from "../data/i18n";

const BEAT = 18; // frames per dhol beat — locked to the 100 BPM soundtrack
const TRAVEL = 380; // camera truck distance (px at the stage plane)
const DRIFT = 150; // the procession walks forward, so it only slides this far across frame

// Procession layout (screen x at the end of the truck).
const HORSE: Pt = [432, 1468];
const UMB = fig(people.guestM1, 122, 1452, 540);
const DH = fig(people.guestM2, 918, 1448, 540);
const HK = fig(people.hardik, 1010, 1576, 620);
const PR = fig(people.pranab, 196, 1560, 660);
const AS = fig(people.ashish, 668, 1590, 630);

/** Bhangra-style dance pose, `d` in [-1,1] swings between the two shapes. */
const dance = (d: number, amp = 1): Partial<Pose> => ({
  lShoulder: 128 + 26 * d * amp,
  lElbow: -40 + 22 * d,
  rShoulder: -128 + 26 * d * amp,
  rElbow: 40 + 22 * d,
  headTilt: 4 * d,
});

/**
 * Baraat departure — a lateral tracking shot along a festive street: palace skyline far, painted
 * havelis and a welcome gate mid, the procession near (ghodi, dhol, dancing brothers), bunting and
 * marigolds crossing the foreground.
 */
export const BaraatScene: React.FC<SceneProps> = ({ inv, dur, beatOffset = 0 }) => {
  const frame = useCurrentFrame();
  // The truck runs the whole shot (the procession keeps walking through the hold).
  const cam = useCamera([
    { frame: 0, x: 0, scale: 1.0 },
    { frame: dur - 2, x: TRAVEL, scale: 1.02, ease: EASE.inOut },
  ]);
  const titleStart = Math.min(64, dur - 110 - 52);
  const p = cam.x / TRAVEL;
  const march = cam.x + DRIFT * (1 - p); // procession offset in stage coordinates
  const beat = ((frame + beatOffset) / BEAT) * Math.PI;
  const bob = (ph = 0, a = 6) => -Math.abs(Math.sin(beat + ph)) * a;
  const gait = frame * 0.2;

  // dhol player: left palm on the bass head, stick swings onto the treble head on the beat
  const dholC = toScene(DH, 200, 600);
  const dholW = 270 * (DH.h / 1000);
  const hit = Math.pow(Math.abs(Math.cos(beat)), 3);
  const stickHand: Pt = [dholC[0] + dholW * 0.46 + 14, dholC[1] - 30 - 44 * (1 - hit)];
  const dPose = { ...reachPose(DH, [dholC[0] - dholW * 0.5, dholC[1] + 4], stickHand, -1, 1), headTilt: 3 * Math.sin(beat) };

  // umbrella bearer
  const uRaise = reach(UMB, "r", [UMB.cx + 120, UMB.feet - 520], 1);
  const uHand = handAt(UMB, "r", uRaise.shoulder, uRaise.elbow);
  const uPose: Partial<Pose> = { rShoulder: uRaise.shoulder, rElbow: uRaise.elbow, lShoulder: 10, lElbow: -12 };
  const canopy: Pt = [HORSE[0] - 42 + Math.sin(gait * 0.5) * 4, 588];

  const item = inv.events.weddingDay.items.find((i) => i.id === "baraat");

  const person = (f: Fig, who: keyof typeof people, outfit: Parameters<typeof Figure>[0]["outfit"], pose: Partial<Pose>, b: number) => (
    <Figure f={f} person={people[who]} outfit={outfit} pose={pose} style={{ transform: `translateY(${b}px)` }} />
  );

  return (
    <Stage background="#F3E3C4">
      <Camera state={cam}>
        {/* SKY — late-morning ivory-gold, the sun climbing its wire */}
        <ParallaxLayer depth={0.06} blurStrength={0}>
          <SVG>
            <SkyGradient id="baraat-sky" top="#F4DDB0" mid="#F8EBCD" bottom="#F5E2BE" />
            <Cloud x={560} y={560} w={280} fill="#FCF1DA" line={palette.goldLight} />
            <Cloud x={-40} y={700} w={220} fill="#FBEED4" />
            <Cloud x={900} y={760} w={240} fill="#FBEFD8" />
            <SunOnWire t={0.33 + prog(frame, 0, dur, EASE.inOut) * 0.04} drop={64} />
          </SVG>
          <PaperBackground stock="cream" seed="baraat-sky" fibres={24} textureOnly />
        </ParallaxLayer>

        {/* FAR — palace skyline */}
        <ParallaxLayer depth={0.28} blurStrength={0}>
          <SVG w={1600}>
            <PalaceSkyline fill="#EBCBA3" y={820} accent="#F6E2C0" />
            <g transform="translate(1080 0)">
              <PalaceSkyline fill="#EBCBA3" y={820} accent="#F6E2C0" />
            </g>
          </SVG>
        </ParallaxLayer>

        {/* MID — festive street: havelis, bunting, a floral welcome gate */}
        <ParallaxLayer depth={0.62} blurStrength={0}>
          <SVG w={1700}>
            <HaveliRow x0={-80} x1={1600} base={1400} seed="baraat-h" />
            <Bunting from={[-60, 930]} to={[520, 950]} sag={40} size={26} seed="bb1" flutter={frame / 9} />
            <Bunting from={[520, 950]} to={[1100, 925]} sag={44} size={26} seed="bb2" flutter={frame / 9 + 1} />
            <Bunting from={[1100, 925]} to={[1660, 950]} sag={40} size={26} seed="bb3" flutter={frame / 9 + 2} />
            <WelcomeGate cx={940} base={1400} w={420} h={600} seed="baraat-gate" sway={wave(frame, 90) * 4} />
            {/* street edge */}
            <rect x={-100} y={1396} width={1900} height={12} fill="#D8BE94" />
            <rect x={-100} y={1396} width={1900} height={2} fill={palette.gold} opacity={0.6} />
          </SVG>
        </ParallaxLayer>

        {/* ROAD — sandstone paving, passing under the procession */}
        <ParallaxLayer depth={1} blurStrength={0}>
          <SVG w={1600}>
            <rect x={-100} y={1406} width={1800} height={620} fill="#EFDFC0" />
            {new Array(14).fill(0).map((_, i) => (
              <rect key={i} x={-100 + i * 140} y={1410} width={1.4} height={600} fill={palette.gold} opacity={0.25} transform={`skewX(${-22 + i * 0})`} />
            ))}
            {[1490, 1600, 1740].map((y) => (
              <rect key={y} x={-100} y={y} width={1800} height={1.2} fill={palette.gold} opacity={0.3} />
            ))}
            {new Array(18).fill(0).map((_, i) => (
              <Petal key={i} x={-40 + i * 92 + (i % 3) * 17} y={1480 + (i % 4) * 26} rot={i * 57} s={1} color={i % 2 ? palette.rose : palette.marigold} />
            ))}
          </SVG>
        </ParallaxLayer>

        {/* PROCESSION — walks forward while the camera trucks */}
        <ParallaxLayer depth={1} blurStrength={0}>
          <AbsoluteFill style={{ transform: `translateX(${march}px)` }}>
            {person(DH, "guestM2", wardrobe.guestM2.festive, dPose, bob(0, 4))}
            <SVG>
              <Dhol x={dholC[0]} y={dholC[1] + bob(0, 4)} w={dholW} tilt={-4} />
              <path
                d={`M${stickHand[0]} ${stickHand[1] + bob(0, 4)} Q${stickHand[0] - 6} ${stickHand[1] + 30} ${dholC[0] + dholW * 0.46} ${dholC[1] - 6 + bob(0, 4)}`}
                fill="none"
                stroke="#6B3A22"
                strokeWidth={3}
                strokeLinecap="round"
              />
              <path d={`M${dholC[0] - dholW * 0.4} ${dholC[1] - 20} L${toScene(DH, 150, 240)[0]} ${toScene(DH, 150, 240)[1]}`} stroke={palette.maroonDeep} strokeWidth={4} transform={`translate(0 ${bob(0, 4)})`} />
            </SVG>
            {person(UMB, "guestM1", wardrobe.guestM1.festive, uPose, 0)}
            <Ghodi
              x={HORSE[0]}
              y={HORSE[1]}
              s={1.1}
              phase={gait}
              id="baraat-ghodi"
              rider={{ person: people.rishabh, outfit: wardrobe.rishabh.wedding, h: 520, sehra: 1, headTilt: wave(frame, 70) * 1.5 }}
            />
            <SVG>
              <Umbrella x={canopy[0]} y={canopy[1]} px={uHand[0]} py={uHand[1]} w={210} swing={Math.sin(gait * 0.5) * 2} />
            </SVG>
            {person(PR, "pranab", wardrobe.pranab.wedding, dance(Math.sin(beat * 1 + 2), 1.2), bob(2, 9))}
            {person(AS, "ashish", wardrobe.ashish.wedding, dance(-Math.sin(beat + 1.2)), bob(1.2, 7))}
            {person(HK, "hardik", wardrobe.hardik.wedding, dance(Math.sin(beat + 0.6)), bob(0.6, 7))}
          </AbsoluteFill>
        </ParallaxLayer>

        {/* FOREGROUND — bunting and marigold strings crossing close to camera */}
        <ParallaxLayer depth={1.45} blurStrength={0} style={{ filter: "blur(5px)" }}>
          <SVG w={1800}>
            <Bunting from={[-120, 40]} to={[640, 120]} sag={70} size={46} seed="bf1" flutter={frame / 7} />
            <Bunting from={[640, 120]} to={[1500, 30]} sag={80} size={46} seed="bf2" flutter={frame / 7 + 2} />
            <GarlandSwag from={[-80, 0]} to={[460, 30]} sag={120} r={22} seed="bfg1" tones={["orange", "yellow", "orange", "rose"]} />
            <GarlandSwag from={[900, 0]} to={[1640, 20]} sag={130} r={22} seed="bfg2" tones={["yellow", "orange", "rose", "orange"]} />
            <Leaf x={-20} y={1880} rot={-30} s={3} color={palette.greenDeep} />
            <Flower x={60} y={1890} r={40} tone="orange" />
            <Flower x={1280} y={1880} r={44} tone="rose" />
            <Flower x={1360} y={1905} r={30} tone="yellow" />
          </SVG>
        </ParallaxLayer>
        <FallingPetals count={14} seed="baraat-petals" speed={0.7} start={-80} size={1.1} />
      </Camera>

      <SceneLighting warmth={0.38} keyX={36} keyY={20} spots={[{ x: 36, y: 22, r: 40, color: "#FFF0C8", intensity: 0.2 }]} vignette={0.36} />

      <AbsoluteFill>
        <Gate from={titleStart}>
          <EventTitle start={titleStart} kicker="The Dulha Rides Out" title={item?.title ?? "Baraat"} lines={[whenBi(inv.events.weddingDay.date, item?.time), bi(inv.events.weddingDay.venue)]} top={1616} titleSize={96} plaque />
        </Gate>
      </AbsoluteFill>

      <GoldFrame />
    </Stage>
  );
};
